import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.BUwdTBzS.js";const v=JSON.parse('{"title":"dev-flow 帮助","description":"","frontmatter":{"title":"dev-flow 帮助"},"headers":[],"relativePath":"dev-flow/references/help.md","filePath":"dev-flow/references/help.md","lastUpdated":null}'),l={name:"dev-flow/references/help.md"};function s(r,t,n,c,i,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/help.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="dev-flow-帮助" tabindex="-1">dev-flow 帮助 <a class="header-anchor" href="#dev-flow-帮助" aria-label="Permalink to &quot;dev-flow 帮助&quot;">​</a></h1><p>系统化 AI 辅助编程开发工作流。从需求输入到代码交付，自动走完整流程（研究→方案→编码→验证→commit）。</p><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我想做什么</th><th>输入</th></tr></thead><tbody><tr><td>开发新功能 / 修 Bug</td><td><code>dev-flow &lt;描述你想做的事&gt;</code></td></tr><tr><td>改个拼写、加个判空</td><td><code>--micro &lt;文件路径&gt; L&lt;行号&gt; &lt;改什么&gt;</code></td></tr><tr><td>同步所有文档</td><td><code>dev:sync</code></td></tr><tr><td>查看当前进度</td><td><code>dev:status</code></td></tr><tr><td>浏览所有功能</td><td><code>dev:ask</code></td></tr></tbody></table><h2 id="流程概览" tabindex="-1">流程概览 <a class="header-anchor" href="#流程概览" aria-label="Permalink to &quot;流程概览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段0 · 需求理解</span></span>
<span class="line"><span>步骤0.5 · 知识库检查（按需）</span></span>
<span class="line"><span>步骤1 · 研究与定位       →  步骤2 · 确认范围       →  步骤3 · 制定方案</span></span>
<span class="line"><span>步骤4 · 方案汇报与用户决策  →  步骤4.5 · 环境检查</span></span>
<span class="line"><span>步骤5 · 执行修改          →  步骤5.5 · 编码后置钩子</span></span>
<span class="line"><span>步骤6 · 质量验证          →  步骤7 · 清理+Commit</span></span></code></pre></div><p>标准模式执行到步骤 7 结束，完整模式继续步骤 8·L3审查→9·反思与学习→10·归档与交付。</p><h2 id="命令大全" tabindex="-1">命令大全 <a class="header-anchor" href="#命令大全" aria-label="Permalink to &quot;命令大全&quot;">​</a></h2><h3 id="流程入口" tabindex="-1">流程入口 <a class="header-anchor" href="#流程入口" aria-label="Permalink to &quot;流程入口&quot;">​</a></h3><p>&lt;!-- CMD_TABLE:process_entry --&gt;</p><table tabindex="0"><thead><tr><th>命令</th><th>模式</th><th>说明</th></tr></thead><tbody><tr><td><code>dev-flow</code></td><td><code>[标准]</code></td><td>进入标准开发流程，步骤 4 智能推荐执行深度</td></tr><tr><td><code>--micro &lt;描述&gt;</code></td><td><code>[快速]</code></td><td>轻量快速修复：≤3 文件 + ≤10 行/文件 + 已知位置</td></tr><tr><td><code>dev:fix --drift</code></td><td><code>[标准]</code></td><td>显式触发需求漂移处理，完成后自动同步文档</td></tr><tr><td><code>dev:fix --iteration</code></td><td><code>[迭代]</code></td><td>显式触发迭代修复，自动匹配已有工作上下文</td></tr></tbody></table><h3 id="管理命令" tabindex="-1">管理命令 <a class="header-anchor" href="#管理命令" aria-label="Permalink to &quot;管理命令&quot;">​</a></h3><p>&lt;!-- CMD_TABLE:management --&gt;</p><table tabindex="0"><thead><tr><th>命令</th><th>别名</th><th>说明</th></tr></thead><tbody><tr><td><code>dev:status</code></td><td><code>dev:st</code></td><td>当前流程进度概览</td></tr><tr><td><code>dev:status --trace</code></td><td>—</td><td>实时观测 Token/红牌/步骤耗时</td></tr><tr><td><code>dev:sync</code></td><td><code>dev:s2</code></td><td>全量文档同步（devlog + knowledge + 文档平台）</td></tr><tr><td><code>dev:kb</code></td><td><code>dev:k</code></td><td>知识库管理（查看/扫描/搜索/沉淀/健康度）</td></tr><tr><td><code>dev:metrics</code></td><td><code>dev:m</code></td><td>度量查看（--all / --trend / --report / --dashboard）</td></tr><tr><td><code>dev:onboard</code></td><td><code>dev:ob</code></td><td>新项目首次接触 / 知识库平台 profile 刷新</td></tr><tr><td><code>dev:flowchart</code></td><td><code>dev:chart</code></td><td>生成/更新 dev-flow 流程图（md + html + png）</td></tr><tr><td><code>dev:ask</code></td><td><code>dev:guide</code></td><td>交互式功能菜单，覆盖所有 dev-flow 功能</td></tr></tbody></table><h3 id="流程内信号-仅-dev-flow-激活时生效" tabindex="-1">流程内信号（仅 dev-flow 激活时生效） <a class="header-anchor" href="#流程内信号-仅-dev-flow-激活时生效" aria-label="Permalink to &quot;流程内信号（仅 dev-flow 激活时生效）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>你可以说</th></tr></thead><tbody><tr><td>迭代修复</td><td><code>提测反馈</code> / <code>继续上次需求</code> / <code>后端接口好了</code></td></tr><tr><td>需求变更</td><td><code>产品说...</code> / <code>刚和 XX 对齐了</code> / <code>需求变了</code> / <code>其实是</code></td></tr><tr><td>分批继续</td><td><code>继续下一批</code> / <code>batch 2</code></td></tr><tr><td>跨项目衔接</td><td><code>跨项目修复衔接</code> / <code>跨项目验证衔接</code></td></tr><tr><td>调整交互</td><td><code>少问我</code> / <code>你决定就好</code>（精简）/ <code>每步都问我</code>（恢复）</td></tr></tbody></table><h3 id="修饰" tabindex="-1">修饰 <a class="header-anchor" href="#修饰" aria-label="Permalink to &quot;修饰&quot;">​</a></h3><p>&lt;!-- CMD_TABLE:modifier --&gt;</p><table tabindex="0"><thead><tr><th>修饰</th><th>作用</th></tr></thead><tbody><tr><td><code>--fast</code></td><td>精简交互，大幅减少确认次数，不减步骤、不降门控</td></tr></tbody></table><h2 id="模式速查" tabindex="-1">模式速查 <a class="header-anchor" href="#模式速查" aria-label="Permalink to &quot;模式速查&quot;">​</a></h2><p>&lt;!-- MODE_TABLE --&gt;</p><table tabindex="0"><thead><tr><th>模式</th><th>适用场景</th><th>步骤</th></tr></thead><tbody><tr><td><code>standard</code></td><td>常规开发</td><td>0→7（全程，含 0.5/4.5/5.5）</td></tr><tr><td><code>full</code></td><td>重要需求、需归档</td><td>0→10（含 8·审查/9·反思/10·归档）</td></tr><tr><td><code>micro-fix</code></td><td>拼写/判空/调参数</td><td>0→4.5→5→5.5→6→7</td></tr><tr><td><code>iteration-fix</code></td><td>提测反馈</td><td>0→1(增量)→2(增量)→3(增量)→4.5→5→5.5→6→7</td></tr><tr><td><code>batch</code></td><td>大批量改动（&gt;5 文件或 &gt;300 行）</td><td>0→7 循环</td></tr><tr><td><code>cross-project</code></td><td>多仓库</td><td>0→7（跨 workspace）</td></tr></tbody></table><h2 id="常见工作流" tabindex="-1">常见工作流 <a class="header-anchor" href="#常见工作流" aria-label="Permalink to &quot;常见工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我想做什么</th><th>使用命令</th></tr></thead><tbody><tr><td>开发新功能 / 修 Bug</td><td><code>dev-flow &lt;描述&gt;</code>，步骤 4 选择执行深度</td></tr><tr><td>改个拼写/加个判空</td><td><code>--micro &lt;文件路径&gt; L&lt;行号&gt; &lt;改动内容&gt;</code></td></tr><tr><td>提测后修反馈</td><td>流程内说 <code>继续上次需求</code></td></tr><tr><td>产品改需求</td><td>流程内说 <code>--drift</code> 或自然描述变更</td></tr><tr><td>从上次中断处继续</td><td>自然描述相关话题，自动恢复</td></tr><tr><td>同步所有文档</td><td><code>dev:sync</code></td></tr><tr><td>搜索/沉淀项目代码知识</td><td><code>dev:kb</code></td></tr><tr><td>查看历史效率数据</td><td><code>dev:metrics --trend</code></td></tr><tr><td>不知道用什么功能</td><td><code>dev:ask</code></td></tr></tbody></table><hr><p>使用 <code>dev:help &lt;命令&gt;</code> 查看特定命令详情 | 使用 <code>dev:help modes</code> 仅查看模式速查 | <code>dev:ask</code> 交互式功能菜单</p><p>全文规范：<code>skills/dev-flow/SKILL.md</code> 模式矩阵：<code>skills/dev-flow/references/mode-matrix.md</code></p><p>&lt;!-- OUTPUT_END --&gt;</p><p>&lt;!-- ═══════════════════════════════════════════ --&gt; &lt;!-- 以下为参考区块：dev:help &lt;命令&gt; 时在此查找对应 CMD_DETAIL 标记 --&gt; &lt;!-- ═══════════════════════════════════════════ --&gt;</p><h2 id="进入方式" tabindex="-1">进入方式 <a class="header-anchor" href="#进入方式" aria-label="Permalink to &quot;进入方式&quot;">​</a></h2><p>dev-flow 有多种入口方式，无需死记，自然表达即可：</p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>显式命令</td><td>主动输入流程命令</td><td><code>dev-flow 开发用户中心页</code></td></tr><tr><td>交互式菜单</td><td>不知道用什么？输入 <code>dev:ask</code> 弹出分类引导菜单</td><td><code>dev:ask</code> → 选中即执行</td></tr><tr><td>活跃流程恢复</td><td>上次没做完？直接说相关的话，AI 自动续上</td><td><code>继续修上次那个登录 bug</code></td></tr><tr><td>文档同步关键词</td><td>说 <code>同步文档</code> / <code>全量同步</code> / <code>检查文档</code> / <code>更新文档</code></td><td>自动触发 <code>dev:sync</code></td></tr><tr><td>AI 主动建议</td><td>说 <code>修复 xxx</code>、发 任务平台/Figma 链接时，AI 会建议你用 dev-flow</td><td>你决定用不用，说「直接改」可跳过流程</td></tr></tbody></table><blockquote><p><code>dev-flow</code> 与 <code>/dev-flow</code> 完全等价（加不加 <code>/</code> 均可）。使用 <code>--help</code> / <code>-h</code> / <code>dev:help</code> / <code>dev:h</code> 随时查看此帮助。</p></blockquote><h2 id="快速示例" tabindex="-1">快速示例 <a class="header-anchor" href="#快速示例" aria-label="Permalink to &quot;快速示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 流程入口</span></span>
<span class="line"><span>dev-flow                                            # 标准开发</span></span>
<span class="line"><span>dev-flow --fast 修复登录页样式问题                     # 精简交互</span></span>
<span class="line"><span>--micro 修复 src/utils/format.ts L42 的拼写             # 快速修复</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 流程内使用</span></span>
<span class="line"><span>继续上次需求                                          # 迭代修复（自动恢复）</span></span>
<span class="line"><span>少问我                                                # 精简交互模式</span></span>
<span class="line"><span>继续下一批                                            # 分批执行</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 管理命令</span></span>
<span class="line"><span>dev:sync                                             # 同步所有文档</span></span>
<span class="line"><span>dev:status                                           # 查看进度</span></span>
<span class="line"><span>dev:status --trace                                   # 实时观测</span></span>
<span class="line"><span>dev:kb                                               # 知识库</span></span>
<span class="line"><span>dev:metrics --trend                                  # 趋势分析</span></span>
<span class="line"><span>dev:onboard                                          # 项目接入</span></span>
<span class="line"><span>dev:flowchart                                        # 生成流程图</span></span>
<span class="line"><span>dev:ask                                              # 交互式功能菜单</span></span>
<span class="line"><span>dev:metrics                                          # 查看度量</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 帮助</span></span>
<span class="line"><span>dev:help                                             # 完整帮助</span></span>
<span class="line"><span>dev:help modes                                       # 仅看模式速查</span></span>
<span class="line"><span>dev:help --micro                                     # 仅看 --micro 命令详情</span></span></code></pre></div><h2 id="命令详情" tabindex="-1">命令详情 <a class="header-anchor" href="#命令详情" aria-label="Permalink to &quot;命令详情&quot;">​</a></h2><p>&lt;!-- CMD_DETAIL:dev-flow --&gt;</p><h3 id="dev-flow-dev" tabindex="-1">dev-flow / dev: <a class="header-anchor" href="#dev-flow-dev" aria-label="Permalink to &quot;dev-flow / dev:&quot;">​</a></h3><ul><li><strong>类型</strong>: 流程入口</li><li><strong>别名</strong>: <code>dev:</code> / <code>/dev-flow</code></li><li><strong>模式</strong>: 标准 / 完整 / 分批（步骤 4 决定）</li><li><strong>说明</strong>: 进入统一开发流程。所有需求走同一入口，执行深度由步骤 4 智能评估推荐</li><li><strong>组合</strong>: 可与 <code>--fast</code> 叠加；流程内可用 <code>--drift</code> / <code>--iteration</code></li><li><strong>相关</strong>: 流程结束时自动在步骤 7 生成 commit message（格式 <code>&lt;type&gt;: &lt;description&gt;</code>） &lt;!-- /CMD_DETAIL:dev-flow --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:--micro --&gt;</p><h3 id="micro-lt-描述" tabindex="-1">--micro &lt;描述&gt; <a class="header-anchor" href="#micro-lt-描述" aria-label="Permalink to &quot;--micro &amp;lt;描述&gt;&quot;">​</a></h3><ul><li><strong>类型</strong>: 流程入口（快速通道）</li><li><strong>模式</strong>: micro-fix</li><li><strong>条件</strong>: ≤3 文件 + ≤10 行/文件 + 用户已知修改位置</li><li><strong>降级</strong>: 实际改动 &gt;15 行 或 &gt;3 文件 或 不对称修改 → 自动降级为标准流程 &lt;!-- /CMD_DETAIL:--micro --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:--fast --&gt;</p><h3 id="fast" tabindex="-1">--fast <a class="header-anchor" href="#fast" aria-label="Permalink to &quot;--fast&quot;">​</a></h3><ul><li><strong>类型</strong>: 修饰（可叠加任意命令）</li><li><strong>说明</strong>: 精简交互频率。绿色流程推进 + 黄色质量检查自动决策，红色关键决策（commit/主干/文档方案）仍暂停确认</li><li><strong>效果</strong>: 大幅减少交互确认次数，不减步骤、不降门控</li><li><strong>切换</strong>: 流程中随时说 <code>少问我</code> 或 <code>你决定就好</code> 进入精简模式，<code>每步都问我</code> 恢复标准模式 &lt;!-- /CMD_DETAIL:--fast --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:dev:fix --drift --&gt;</p><h3 id="dev-fix-drift" tabindex="-1">dev:fix --drift <a class="header-anchor" href="#dev-fix-drift" aria-label="Permalink to &quot;dev:fix --drift&quot;">​</a></h3><ul><li><strong>类型</strong>: 显式命令（新对话/流程内外均可使用）</li><li><strong>说明</strong>: 显式触发需求漂移处理。产品改需求或方案对齐后使用，完成后自动调用 dev:sync 同步下游文档</li><li><strong>对比流程内信号</strong>: 流程内直接说 <code>--drift</code> 或描述变更即可，无需输入完整命令 &lt;!-- /CMD_DETAIL:dev:fix --drift --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:dev:fix --iteration --&gt;</p><h3 id="dev-fix-iteration" tabindex="-1">dev:fix --iteration <a class="header-anchor" href="#dev-fix-iteration" aria-label="Permalink to &quot;dev:fix --iteration&quot;">​</a></h3><ul><li><strong>类型</strong>: 显式命令（新对话/流程内外均可使用）</li><li><strong>说明</strong>: 显式触发迭代修复。提测反馈或后端接口就绪后使用，自动匹配已有工作上下文</li><li><strong>对比流程内信号</strong>: 流程内直接说 <code>继续上次需求</code> 即可，无需输入完整命令 &lt;!-- /CMD_DETAIL:dev:fix --iteration --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:--drift --&gt;</p><h3 id="drift-流程内信号" tabindex="-1">--drift（流程内信号） <a class="header-anchor" href="#drift-流程内信号" aria-label="Permalink to &quot;--drift（流程内信号）&quot;">​</a></h3><ul><li><strong>类型</strong>: 流程内信号（仅 dev-flow 激活时生效）</li><li><strong>说明</strong>: 处理需求漂移。完成后自动调用 dev:sync 同步下游文档</li><li><strong>触发词</strong>: <code>产品说</code> / <code>刚和 XX 对齐</code> / <code>需求变了</code> / <code>其实是</code> &lt;!-- /CMD_DETAIL:--drift --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:--iteration --&gt;</p><h3 id="iteration-流程内信号" tabindex="-1">--iteration（流程内信号） <a class="header-anchor" href="#iteration-流程内信号" aria-label="Permalink to &quot;--iteration（流程内信号）&quot;">​</a></h3><ul><li><strong>类型</strong>: 流程内信号（仅 dev-flow 激活时生效）</li><li><strong>说明</strong>: 触发迭代修复。自动匹配已有工作上下文，增量执行</li><li><strong>触发词</strong>: <code>提测反馈</code> / <code>继续上次需求</code> / <code>后端接口好了</code> &lt;!-- /CMD_DETAIL:--iteration --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:dev:sync --&gt;</p><h3 id="dev-sync-dev-s2" tabindex="-1">dev:sync / dev:s2 <a class="header-anchor" href="#dev-sync-dev-s2" aria-label="Permalink to &quot;dev:sync / dev:s2&quot;">​</a></h3><ul><li><strong>类型</strong>: 管理命令（流程内外均可使用）</li><li><strong>说明</strong>: 全量文档同步（devlog + knowledge + 技术方案文档）</li><li><strong>流程内模式</strong>（dev-flow 激活时）：同步当前需求的文档，自动识别需同步的范围</li><li><strong>流程外模式</strong>（独立调用）：自动匹配最近的工作上下文进行同步</li><li><strong>自动触发节点</strong>：AI 在 5.5 累计 ≥3 次、完整模式追加改动、drift 完成后等节点主动弹框提醒</li><li><strong>重要</strong>: <code>dev:sync</code> 是补救兜底，不是日常 <code>5.5b 文档同步</code> 的替代品 &lt;!-- /CMD_DETAIL:dev:sync --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:dev:status --&gt;</p><h3 id="dev-status-dev-st" tabindex="-1">dev:status / dev:st <a class="header-anchor" href="#dev-status-dev-st" aria-label="Permalink to &quot;dev:status / dev:st&quot;">​</a></h3><ul><li><strong>类型</strong>: 管理命令</li><li><strong>说明</strong>: 扫描活跃流程文件和工作上下文，展示当前进度（步骤/模式/交互方式）</li><li><strong>选项</strong>: <code>--trace</code> 实时观测 Token 消耗、红牌次数、步骤耗时 &lt;!-- /CMD_DETAIL:dev:status --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:dev:kb --&gt;</p><h3 id="dev-kb-dev-k" tabindex="-1">dev:kb / dev:k <a class="header-anchor" href="#dev-kb-dev-k" aria-label="Permalink to &quot;dev:kb / dev:k&quot;">​</a></h3><ul><li><strong>类型</strong>: 管理命令</li><li><strong>说明</strong>: 项目代码知识库管理。支持查看/扫描/搜索/沉淀/健康度检查</li><li><strong>示例</strong>: <code>dev:kb</code> 弹出交互式选项（查看模块/扫描代码/检查健康度） &lt;!-- /CMD_DETAIL:dev:kb --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:dev:metrics --&gt;</p><h3 id="dev-metrics-dev-m" tabindex="-1">dev:metrics / dev:m <a class="header-anchor" href="#dev-metrics-dev-m" aria-label="Permalink to &quot;dev:metrics / dev:m&quot;">​</a></h3><ul><li><strong>类型</strong>: 管理命令</li><li><strong>说明</strong>: 开发流程度量数据查看</li><li><strong>选项</strong>: <code>--all</code> 全部历史 / <code>--trend</code> 趋势分析 / <code>--report &lt;ID&gt;</code> 指定需求 / <code>--dashboard</code> 可视化仪表盘 &lt;!-- /CMD_DETAIL:dev:metrics --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:dev:onboard --&gt;</p><h3 id="dev-onboard-dev-ob" tabindex="-1">dev:onboard / dev:ob <a class="header-anchor" href="#dev-onboard-dev-ob" aria-label="Permalink to &quot;dev:onboard / dev:ob&quot;">​</a></h3><ul><li><strong>类型</strong>: 管理命令</li><li><strong>说明</strong>: 新项目首次接触时生成 知识库平台 profile（L0 缓存），或手动刷新已有 profile</li><li><strong>选项</strong>: <code>--refresh</code>/<code>-r</code> 全量刷新 / <code>--refresh-recent</code>/<code>-rr</code> 增量刷新 / <code>--check</code>/<code>-c</code> 只校验不刷新 &lt;!-- /CMD_DETAIL:dev:onboard --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:dev:ask --&gt;</p><h3 id="dev-ask-dev-guide" tabindex="-1">dev:ask / dev:guide <a class="header-anchor" href="#dev-ask-dev-guide" aria-label="Permalink to &quot;dev:ask / dev:guide&quot;">​</a></h3><ul><li><strong>类型</strong>: 管理命令</li><li><strong>说明</strong>: dev-flow 全功能交互式入口。弹出分类菜单，逐级引导到具体命令，选中即执行</li><li><strong>别名</strong>: <code>dev:guide</code></li><li><strong>特点</strong>: 状态感知（根据当前是否有活跃流程动态显示选项）、场景向导（不确定用什么时帮你判断） &lt;!-- /CMD_DETAIL:dev:ask --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:dev:flowchart --&gt;</p><h3 id="dev-flowchart-dev-chart" tabindex="-1">dev:flowchart / dev:chart <a class="header-anchor" href="#dev-flowchart-dev-chart" aria-label="Permalink to &quot;dev:flowchart / dev:chart&quot;">​</a></h3><ul><li><strong>类型</strong>: 管理命令</li><li><strong>说明</strong>: 生成/更新 dev-flow 流程图，输出 md + html + png 三种格式。支持覆盖当前版本、另存新版本两种更新方式 &lt;!-- /CMD_DETAIL:dev:flowchart --&gt;</li></ul><p>&lt;!-- CMD_DETAIL:dev:help --&gt;</p><h3 id="dev-help-dev-h" tabindex="-1">dev:help / dev:h <a class="header-anchor" href="#dev-help-dev-h" aria-label="Permalink to &quot;dev:help / dev:h&quot;">​</a></h3><ul><li><strong>类型</strong>: 帮助命令</li><li><strong>说明</strong>: 显示本帮助。支持 <code>dev:help &lt;命令&gt;</code> 查看单条命令详情，<code>dev:help modes</code> 仅查看模式速查 &lt;!-- /CMD_DETAIL:dev:help --&gt;</li></ul>`,82)])])}const g=d(l,[["render",s]]);export{v as __pageData,g as default};
